class Solution {
public:
    const long long MOD = 1e9 + 7;
    long long pw(long long b, long long e) {
        long long r = 1; b %= MOD;
        while (e) { if (e & 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return r;
    }
    int stringCount(int n) {
        auto f = [&](long long b) { return (pw(b, n) + n % MOD * pw(b, n - 1)) % MOD; };
        long long bad = (2 * pw(25, n) + f(25) - pw(24, n) - 2 * f(24) + f(23)) % MOD;
        return (int)((pw(26, n) - bad % MOD + MOD) % MOD);
    }
};

