class Solution {
    private static final long MOD = 1_000_000_007L;
    private long pw(long b, long e) {
        long r = 1; b %= MOD;
        while (e > 0) { if ((e & 1) == 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return r;
    }
    public int stringCount(int n) {
        long f25 = (pw(25, n) + (long) n % MOD * pw(25, n - 1)) % MOD;
        long f24 = (pw(24, n) + (long) n % MOD * pw(24, n - 1)) % MOD;
        long f23 = (pw(23, n) + (long) n % MOD * pw(23, n - 1)) % MOD;
        long bad = (2 * pw(25, n) % MOD + f25 - pw(24, n) - 2 * f24 % MOD + f23 + 2L * MOD) % MOD;
        return (int) ((pw(26, n) - bad + MOD) % MOD);
    }
}

