var stringCount = function(n) {
    const MOD = 1e9 + 7;
    const pw = (b, e) => { let r = 1n, bb = BigInt(b) % BigInt(MOD), ee = BigInt(e); while (ee > 0n) { if (ee & 1n) r = r * bb % BigInt(MOD); bb = bb * bb % BigInt(MOD); ee >>= 1n; } return r; };
    const nn = BigInt(n) % BigInt(MOD);
    const f = (b) => (pw(b, n) + nn * pw(b, n - 1)) % BigInt(MOD);
    const bad = (2n * pw(25, n) + f(25) - pw(24, n) - 2n * f(24) + f(23) + 4n * BigInt(MOD)) % BigInt(MOD);
    return Number((pw(26, n) - bad + BigInt(MOD)) % BigInt(MOD));
};
